### 3. Модель экрана «Цитаты книги» (тот же пакет)

```swift
// SlumpyCore/Sources/SlumpyCore/Quotes/BookQuotesModel.swift
import Foundation
import Observation

@MainActor
@Observable
public final class BookQuotesModel {
    public enum Problem: Equatable, Sendable {
        case loadFailed, addFailed, deleteFailed
    }

    public let bookID: UUID
    public private(set) var quotes: [BookQuote] = []
    public private(set) var isLoaded = false
    /// Экран показывает предупреждение и сбрасывает значение в nil.
    public var problem: Problem?

    private let store: any QuoteStore
    /// Номер последней загрузки: устаревший ответ не затрёт свежий список.
    private var generation = 0

    public init(bookID: UUID, store: any QuoteStore) {
        self.bookID = bookID
        self.store = store
    }

    public func reload() async {
        generation += 1
        let current = generation
        do {
            let fresh = try await store.quotes(ofBook: bookID)
            guard current == generation else { return }
            quotes = fresh
            isLoaded = true
        } catch {
            guard current == generation else { return }
            problem = .loadFailed
        }
    }

    /// Возвращает false, если текст пустой или сохранить не удалось.
    @discardableResult
    public func add(text: String) async -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }
        generation += 1
        let quote = BookQuote(id: UUID(), text: trimmed, bookID: bookID, createdAt: .now)
        do {
            try await store.add(quote)
        } catch {
            problem = .addFailed
            return false
        }
        await reload()
        return true
    }

    public func delete(_ quote: BookQuote) async {
        generation += 1
        // Строка исчезает сразу; если удалить не вышло, reload вернёт её.
        quotes.removeAll { $0.id == quote.id }
        do {
            try await store.delete(quoteID: quote.id)
        } catch {
            problem = .deleteFailed
        }
        await reload()
    }
}
```

