    }

    public func reload() async {
        generation += 1
        let current = generation
        do {
            let fresh = try await store.quotes(ofBook: bookID)
            guard current == generation else { return }
            quotes = fresh
            isLoaded = true
        } catch {
            guard current == generation else { return }
            problem = .loadFailed
        }
    }

    /// Возвращает false, если текст пустой или сохранить не удалось.
    @discardableResult
    public func add(text: String) async -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return false }
        generation += 1
        let quote = BookQuote(id: UUID(), text: trimmed, bookID: bookID, createdAt: .now)
        do {
            try await store.add(quote)
        } catch {
            problem = .addFailed
            return false
        }
        await reload()
        return true
    }

    public func delete(_ quote: BookQuote) async {
        generation += 1
        // Строка исчезает сразу; если удалить не вышло, reload вернёт её.
        quotes.removeAll { $0.id == quote.id }
        do {
            try await store.delete(quoteID: quote.id)
        } catch {
            problem = .deleteFailed
        }
        await reload()
    }
}
```

### 4. Реализация на SwiftData (приложение)

```swift
// Slumpy/Storage/SwiftDataQuoteStore.swift
import Foundation
import SwiftData
import SlumpyCore

@MainActor
final class SwiftDataQuoteStore: QuoteStore {
    private let context: ModelContext

    init(container: ModelContainer) {
        context = ModelContext(container)
        context.autosaveEnabled = false
    }

    func quotes(ofBook bookID: UUID) async throws -> [BookQuote] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try context.fetch(descriptor).map { BookQuote($0) }
    }

    func add(_ quote: BookQuote) async throws {
        context.insert(Quote(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt))
        try saveOrRollback()
    }

    func delete(quoteID: UUID) async throws {
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate { $0.id == quoteID })
        for model in try context.fetch(descriptor) {
            context.delete(model)
        }
        try saveOrRollback()
    }

    /// Неудачное сохранение не должно оставить «полузаписанные» изменения на следующий раз.
    private func saveOrRollback() throws {
        do {
            try context.save()
        } catch {
            context.rollback()
            throw error
        }
    }
}

private extension BookQuote {
    init(_ model: Quote) {
        self.init(id: model.id, text: model.text, bookID: model.bookID, createdAt: model.createdAt)
    }
}
